FILE = "one-woman-one-bra-amaa-best-film.html"
TITLE = "Kenya's One Woman One Bra wins Best Film at the 2026 AMAAs"
TAG = "The Wrap"
H1 = "Kenya takes Best Film at the AMAAs"
DEK = "Vincho Nchogu's One Woman One Bra won the top prize at the Africa Movie Academy Awards in Lagos, one of three awards it took home on the night."
META = "The Wrap · Local · 17 Nov 2026 · 3 min read"
LEAD = ("img/wr-one-woman-one-bra-amaa.jpg", "The One Woman One Bra team with their awards at the AMAAs in Lagos", "@1woman1bra / Instagram")

BODY = [
("p", "One Woman One Bra, written and directed by Kenyan filmmaker Vincho Nchogu, won Best Film at the 2026 Africa Movie Academy Awards. The ceremony was held at the Marriott Hotel in Ikeja, Lagos, on Sunday, 15 November 2026."),
("p", "It was one of three wins for the film. It also took the Ousmane Sembène Award for Best Film in an African Language, and Nchogu won Best Debut Feature Film by a Director."),
("h2", "The night", "Three awards from ", "14 nominations"),
("p", "The film went into the night with 14 nominations, level with Uganda's Slum Bomber for the most of any film this year. Its three wins all came in the film categories. It didn't win in the acting, technical or craft categories."),
("p", "Slum Bomber, which won Best Feature Film at the Africa International Film Festival (AFRIFF) in Lagos earlier this month, left with one award: Samuel Kabugo won Best Actor in a Supporting Role."),
("h2", "The film", "From Venice ", "to Lagos"),
("p", "One Woman One Bra is Nchogu's first feature. It's a Kenya-Nigeria co-production, produced by Nigeria's Josh Olaoluwa through his Lagos company Conceptified Media and shot in Kenya by Nigerian cinematographer Muhammad Atta Ahmed."),
("p", "It's a comedy-drama about a woman's rights and her control over her own life, and it saves some of its sharpest jokes for Western charities and NGOs. Nchogu drew on her own years making promotional work for NGOs across East Africa."),
("p", "The film was made through the Biennale College Cinema programme and had its world premiere at the 82nd Venice International Film Festival on 27 August 2025. It then won the Sutherland Award for best first feature at the BFI London Film Festival, and it is Kenya's submission for Best International Feature Film at the 99th Academy Awards."),
("p", "Sunday's win in Lagos adds the continent's own top film prize to that run."),
]

